import{_ as a,o as t,c as n,a2 as i}from"./chunks/framework.CDpkVv68.js";const u=JSON.parse('{"title":"Stamina, recovery and combat cadence","description":"","frontmatter":{},"headers":[],"relativePath":"en/game-design/combat/stamina-and-reactive-combat.md","filePath":"en/game-design/combat/stamina-and-reactive-combat.md"}'),r={name:"en/game-design/combat/stamina-and-reactive-combat.md"};function o(s,e,c,d,l,p){return t(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="stamina-recovery-and-reactive-combat" tabindex="-1">Stamina, recovery and combat cadence <a class="header-anchor" href="#stamina-recovery-and-reactive-combat" aria-label="Permalink to &quot;Stamina, recovery and combat cadence&quot;">​</a></h1><p><strong>Design status: Accepted automatic baseline; Proposed stamina/fatigue expansion and manual-input direction; Unresolved compatibility between them. Implementation: inherited server timing, no Batch 03 input or resource changes.</strong></p><p><a href="/Syrolands-Public/en/guide/combat/stamina-and-reactive-combat.html">Player guide</a> · <a href="/Syrolands-Public/en/game-design/combat/overview.html">Combat foundations</a></p><h2 id="automatic-baseline-and-manual-input-conflict" tabindex="-1">Automatic baseline and manual-input conflict <a class="header-anchor" href="#automatic-baseline-and-manual-input-conflict" aria-label="Permalink to &quot;Automatic baseline and manual-input conflict&quot;">​</a></h2><p>Combat Design v0.2 sections 2 and 11 preserve ordinary automatic swings and optional advanced interaction. Preparing intent for a scheduled swing does not grant an extra attack. Optional held-ready swings are exploratory.</p><p>Batch 03 proposes a configurable attack key (Space is an example, not an approved binding), a manually triggered attempt, visible animation, stamina/fatigue cost, recovery and weapon-specific timing. Its goal is meaningful timing, positioning and player execution. <strong>Making manual input mandatory for every attack would conflict with the Accepted automatic baseline.</strong> The source does not establish whether this is an optional mode or a replacement.</p><p><strong>Historical Batch 03 decision gap, clarified by Batch 05 below:</strong> two decisions remained open: explore optional manual/held-ready interaction while retaining automatic combat, or explicitly revise the approved baseline before evaluating a replacement. Neither option was selected by Batch 03. The conflicting replacement is not implemented or promoted to Accepted. Optional input still needs a technical contract and gameplay evaluation; calling it optional does not make it already approved in detail.</p><h2 id="proposed-stamina-and-fatigue" tabindex="-1">Proposed stamina and fatigue <a class="header-anchor" href="#proposed-stamina-and-fatigue" aria-label="Permalink to &quot;Proposed stamina and fatigue&quot;">​</a></h2><p>Stamina is the preferred physical resource to investigate, without automatically copying AOS martial mana costs. Candidate uses include attack commitment, recovery, repeated-action pressure, pursuit and movement, heavy equipment, precision/control and tactical pacing. Sustained high-impact actions should not be indefinitely free. Whether fatigue is derived from stamina or separately represented is Unresolved.</p><p>No attack cost, regeneration curve, exhaustion penalty or recovery duration is fixed here. Misses, canceled attempts, invalid targets, repeated input and failed actions need explicit charging rules before implementation. Stamina cost, recovery, cooldown, attack opportunity and visual animation duration are distinct concepts.</p><h2 id="responsiveness-and-inheritance-gap" tabindex="-1">Responsiveness and inheritance gap <a class="header-anchor" href="#responsiveness-and-inheritance-gap" aria-label="Permalink to &quot;Responsiveness and inheritance gap&quot;">​</a></h2><p><a href="/Syrolands-Public/en/game-design/characters/stats.html">Stats</a> owns the Proposed bounded DEX/STR/INT roles. Low DEX should not make baseline combat feel like slow motion. Weapon class, attack type, stance, recovery, fatigue, encumbrance and technique are proposed primary cadence factors; DEX may have bounded influence on recovery or precision. These are design goals, not a new formula.</p><p>Inherited pre-AOS attack timing uses current stamina and weapon speed, not DEX directly; inherited damage incorporates STR, Tactics and Anatomy. Those relationships are compatibility gaps to reconcile, not final Syrolands approval. No new client-input or animation evaluation was performed for this batch, and Space support is not established.</p><h2 id="authority-and-presentation" tabindex="-1">Authority and presentation <a class="header-anchor" href="#authority-and-presentation" aria-label="Permalink to &quot;Authority and presentation&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Category</th><th>Boundary for a future design</th></tr></thead><tbody><tr><td>USER INTENT</td><td>Request an attack or preferred region/technique through a remappable input</td></tr><tr><td>AUTHORITATIVE SERVER STATE</td><td>Validate target, range, LOS, timing and resources; resolve hit, actual region, damage, trauma and recovery</td></tr><tr><td>SYNCHRONIZED STATE</td><td>Replicate only server-approved outcomes and permitted opportunity/assessment information</td></tr><tr><td>CLIENT PRESENTATION</td><td>Show cues, animation and feedback; anticipation never grants a hit or dictates timing</td></tr></tbody></table><p>Authoritative gameplay cannot wait for rendering or animation completion. No packet identifier, capability gate, input queue, prediction policy or latency compensation is selected here. Future interaction designs must define compatible behavior and fallback. Accessibility/remapping, latency fairness and automation resistance are unresolved design requirements, not justification for a client-authoritative hitbox.</p><h2 id="concentration-pressure" tabindex="-1">Concentration pressure <a class="header-anchor" href="#concentration-pressure" aria-label="Permalink to &quot;Concentration pressure&quot;">​</a></h2><p>Damage, local trauma, movement, repeated pressure, stun/impact and certain weapon traits are proposed candidates for interrupting or stressing magical Concentration. <a href="/Syrolands-Public/en/game-design/magic.html#concentration-under-pressure">Magic owns Concentration</a>, its representation and unresolved formulas, including the distinction between <a href="/Syrolands-Public/en/game-design/magic.html#fizzle-versus-interruption">fizzle and interruption</a>. This page does not create a new stun rule or declare every hit an automatic interruption.</p><h2 id="related-design" tabindex="-1">Related design <a class="header-anchor" href="#related-design" aria-label="Permalink to &quot;Related design&quot;">​</a></h2><p><a href="/Syrolands-Public/en/game-design/combat/status-and-open-questions.html">Status and unresolved decisions</a></p><h2 id="spellbook-pressure-—-batch-04" tabindex="-1">Spellbook pressure — Batch 04 <a class="header-anchor" href="#spellbook-pressure-—-batch-04" aria-label="Permalink to &quot;Spellbook pressure — Batch 04&quot;">​</a></h2><p><a href="/Syrolands-Public/en/game-design/magic/memory-and-familiarity.html#physical-reference-under-pressure">Physical reference under pressure</a> proposes book navigation and recall before casting a known unmemorized spell. Damage, fatigue, movement and local trauma may pressure Concentration under its existing <a href="/Syrolands-Public/en/game-design/magic.html#meditation-and-concentration">magic owner</a>. This selects no cast/attack timing, binding or mandatory melee input and does not resolve the automatic/manual conflict above.</p><h2 id="batch-05-clarification" tabindex="-1">Batch 05 clarification <a class="header-anchor" href="#batch-05-clarification" aria-label="Permalink to &quot;Batch 05 clarification&quot;">​</a></h2><p><a href="/Syrolands-Public/en/game-design/combat/legacy-and-modern.html">Legacy and Modern Combat</a> is the current Proposed terminology: Legacy automatic cadence versus Modern player-triggered initiation, with shared target selection and resource/action rules. Modern is the preferred experimental direction while Legacy remains a supported alternative in the proposal. Thus Batch 05 does not require all players to abandon automatic attacks; implementation and formal acceptance remain separate gates. “Reactive” survives in historical section/route names, not as the primary mode label.</p><p><a href="/Syrolands-Public/en/game-design/combat/flow.html">Flow</a>, <a href="/Syrolands-Public/en/game-design/combat/actions.html">action phases</a> and <a href="/Syrolands-Public/en/game-design/combat/variable-registry.html">the variable registry</a> refine stamina/cadence questions without choosing formulas. The earlier source and Accepted experimental scope remain intact.</p><h2 id="batch-06-numeric-test-scope" tabindex="-1">Batch 06 numeric test scope <a class="header-anchor" href="#batch-06-numeric-test-scope" aria-label="Permalink to &quot;Batch 06 numeric test scope&quot;">​</a></h2><p>The <a href="/Syrolands-Public/en/game-design/combat/numeric-prototype.html">three-weapon profile</a> assigns Experimental test values for Longsword, Spear and War Hammer. Its phase, resource, cadence, Flow, martial Familiarity and preparation rules apply only to that future test. Earlier examples remain historical alternatives outside this profile; no final balance, gameplay implementation or spell-number assignment follows.</p>',27)])])}const h=a(r,[["render",o]]);export{u as __pageData,h as default};
